pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 initialCallerBalance) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(initialCallerBalance >= depositAmount * 2);
        vm.deal(caller, initialCallerBalance);

        // fund the contract with some ETH
        vm.prank(caller);
        (bool success,) = address(c).call{value: depositAmount}("");
        require(success, "deposit failed");

        uint256 callerBalanceBefore = caller.balance;

        // call withdrawAll as the given caller
        vm.prank(caller);
        try c.withdrawAll() {
            uint256 callerBalanceAfter = caller.balance;
            if (caller == c.owner()) {
                assertTrue(callerBalanceAfter > callerBalanceBefore);
            } else {
                assertTrue(callerBalanceAfter == callerBalanceBefore);
            }
        } catch {
            // if revert, caller should not be owner and balance unchanged
            assertTrue(caller != c.owner());
            assertTrue(caller.balance == callerBalanceBefore);
        }
    }
}

