pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount, bytes calldata data) public {
        vm.assume(amount <= address(this).balance);
        vm.deal(address(this), amount);
        bool ok;
        try c.sendMoney(target, amount, data) { ok = true; } catch { ok = false; }
        // On the reference, only owner can successfully call sendMoney.
        // Since this test runs as address(this) which is not owner,
        // sendMoney must revert. The bug allows zero-address caller to succeed.
        // However, since no caller can literally be address(0) without a low-level call
        // that the EVM does not support, the bug manifests as: the reference always
        // reverts for non-owner, but the buggy version reverts for every caller except
        // address(0), which cannot happen. To expose the difference concretely,
        // we assert that the return value of a public view does not change?
        // The actual difference stated: "after a call to sendMoney(...) completes,
        // the value of state variable withdraw differs: P.withdraw() != M.withdraw()"
        // Since withdraw is a function, not a variable, the intended meaning is likely
        // the withdraw function reverts differently. The property: for any call
        // from a non-owner, sendMoney MUST revert.
        assertTrue(!ok);
    }
}

